test('CV-04: 重试进行中按钮禁用，重复点击不产生并发请求', async () => {
	const never = new Promise(() => { });
	const { T, viewDownloads } = loadLauncher({
		versions: (n) => { if (n === 1) throw new Error('首次失败'); return never; },
		tasks: () => [],
	});
